.mission-list {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.mission-list__progress {
  margin: 0;
  text-align: center;
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--farm-accent-dark);
}

.mission-list__done {
  text-align: center;
  font-size: 0.9rem;
  font-weight: 800;
  color: var(--farm-accent-dark);
  padding: 0.6rem;
  border-radius: 0.75rem;
  background: var(--farm-cream-dark);
  border: 1.5px dashed var(--farm-accent-dark);
}

.mission-list__cards {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}
